import { Exercise } from '../types';

/**
 * Demonstration media for the built-in catalogue (generated by scripts/generate_exercise_media.py).
 * Each exercise has 3 frames (inicial / intermediária / final) and an animated GIF.
 */
const PHOTO_CREDIT = 'Fotos: Free Exercise DB (domínio público) — movimento equivalente em solo';
const ILLUSTRATION_CREDIT = 'Ilustração esquemática do movimento no aparelho';

const MEDIA: Record<string, Exercise['mediaSource']> = {
  'ex-ref-1': 'ilustracao',
  'ex-ref-2': 'foto',
  'ex-ref-3': 'ilustracao',
  'ex-ref-4': 'ilustracao',
  'ex-ref-5': 'ilustracao',
  'ex-chr-1': 'foto',
  'ex-chr-2': 'foto',
  'ex-chr-3': 'foto',
  'ex-chr-4': 'ilustracao',
  'ex-sol-1': 'foto',
  'ex-sol-2': 'foto',
  'ex-sol-3': 'foto',
  'ex-mob-1': 'ilustracao',
  'ex-mob-2': 'ilustracao',
};

const base = `${import.meta.env.BASE_URL}exercises`;

/** Fill in catalogue media for exercises saved before the media existed (keeps user uploads intact) */
export function withExerciseMedia(ex: Exercise): Exercise {
  const source = MEDIA[ex.id];
  if (!source || ex.mediaSource === 'upload') return ex;
  return {
    ...ex,
    gifUrl: `${base}/${ex.id}/sequencia.gif`,
    mediaSource: source,
    mediaCredit: source === 'foto' ? PHOTO_CREDIT : ILLUSTRATION_CREDIT,
    steps: ex.steps.map((s, i) => ({
      ...s,
      imageUrl: s.imageUrl && !s.imageUrl.startsWith(base) ? s.imageUrl : `${base}/${ex.id}/${Math.min(i, 2) + 1}.jpg`,
    })),
  };
}
